tasks.check:
set -o pipefail
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD:$PWD/scripts/ringer/stage7 TMPDIR=/tmp
PY=.venv/bin/python
F="scripts/ringer/phase1/act3a_probe.py scripts/ringer/phase1/check_act3a_probe.py tests/test_act3a_probe.py"
git status --porcelain | grep -v '^?? .venv$' | awk '{print $2}' | sort > /tmp/chg.$$
printf '%s\n' $F | sort > /tmp/alw.$$
[ -z "$(comm -23 /tmp/chg.$$ /tmp/alw.$$)" ] || { echo "WHY: files outside ownership changed:"; comm -23 /tmp/chg.$$ /tmp/alw.$$; exit 1; }
for f in $F; do [ -f $f ] || { echo "WHY: missing $f"; exit 1; }; done
grep -q "from act2_probe import\|from .act2_probe import" scripts/ringer/phase1/act3a_probe.py || { echo "WHY: act3a_probe must import act2_probe helpers"; exit 1; }
$PY -m pytest -q -p no:cacheprovider tests/test_act3a_probe.py tests/test_act2_probe.py 2>&1 | tail -20
[ "${PIPESTATUS[0]}" = 0 ] || { echo "WHY: focused tests failed"; exit 1; }
for L in transmit rescue; do
  OUT=/tmp/act3a-dry-$L-$$; rm -rf $OUT
  $PY scripts/ringer/phase1/act3a_probe.py --ledger $L --n 1 --dry-run --out $OUT || { echo "WHY: CLI dry run failed for ledger $L"; exit 1; }
  $PY scripts/ringer/phase1/check_act3a_probe.py $OUT 1 --mode dry || { echo "WHY: checker failed on dry $L artifact"; exit 1; }
done
$PY scripts/ringer/phase1/act3a_probe.py --ledger transmit --n 1 --out /tmp/act3a-noconfirm-$$ >/dev/null 2>&1 && { echo "WHY: live mode without --confirm must fail"; exit 1; }
$PY -m ruff format --check $F && $PY -m ruff check $F || { echo "WHY: ruff"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/act3a-reunion-radio
mkdir -p $OUT && git add -- $F && git diff --cached > $OUT/act3a-probe.patch && wc -l $OUT/act3a-probe.patch && git diff --cached --stat | tail -5
